  L: [[2,4],[6,9],[11,11]],
};

function blank() {
  const g = Array.from({length: H}, () => Array(W).fill('.'));
  // border
  for (let x = 0; x < W; x++) { g[0][x] = '#'; g[H-1][x] = '#'; }
  for (let y = 0; y < H; y++) { g[y][0] = '#'; g[y][W-1] = '#'; }
  return g;
}

function paint(g, x1, y1, x2, y2, ch = '#') {
  for (let y = y1; y <= y2; y++) for (let x = x1; x <= x2; x++) {
    if (x < 0 || x >= W || y < 0 || y >= H) throw new Error(`block out of bounds ${x1},${y1},${x2},${y2}`);
    if (x === 0 || x === W-1 || y === 0 || y === H-1) throw new Error(`block hits border ${x1},${y1},${x2},${y2}`);
    if (g[y][x] !== '.') throw new Error(`block overlaps at ${x},${y}`);
    g[y][x] = ch;
  }
}

function section(g, pat, y) {
  const p = PATTERNS[pat];
  const h = 2; // block spans y..y+h (3 tall)
  for (const item of p) {
    if (item === 'C') paint(g, 13, y-1, 14, y+h);
    else { paint(g, item[0], y, item[1], y+h); paint(g, W-1-item[1], y, W-1-item[0], y+h); }
  }
}

function house(g) {
  // walls of the ghost house, rows 15..18, x 10..17
  paint(g, 10, 15, 10, 18);
  paint(g, 17, 15, 17, 18);
  paint(g, 11, 15, 12, 15); // top wall left of door
  paint(g, 15, 15, 16, 15); // top wall right of door
  paint(g, 11, 18, 16, 18); // bottom wall
  // interior + door stay empty
  for (let y = 15; y <= 18; y++) for (let x = 11; x <= 16; x++) if (g[y][x] === '.') g[y][x] = ' ';
}

function tunnel(g) {
  // rows 14-15 open ends, empty corridor at the edges
  for (const y of [14, 15]) {
    g[y][0] = ' '; g[y][W-1] = ' ';
    for (let x = 1; x <= 2; x++) g[y][x] = ' ';
    for (let x = W-3; x <= W-2; x++) g[y][x] = ' ';
  }
}

function spawnClear(g) {
  // empty run under the house where Pac-Man starts
  for (let x = 11; x <= 16; x++) if (g[19][x] !== '#') g[19][x] = ' ';
}

function pellets(g, spots) {
  for (const [x, y] of spots) {
    if (g[y][x] !== '.') throw new Error(`pellet ${x},${y} on wall`);
    g[y][x] = 'o';
    g[y][W-1-x] = 'o';
  }
}

function render(spec) {
  const g = blank();
  for (const [pat, y] of spec.top) section(g, pat, y);
