  pellets(g, spec.pellets);
  const rows = g.map(r => r.join(''));
  rows.forEach((r, i) => { if (r.length !== W) throw new Error(`row ${i} len ${r.length}`); });
  if (rows.length !== H) throw new Error('bad height');
  return rows;
}

